{
"id": "mysql-05-join",
"num": 5,
"title": "JOIN and GROUP BY: answering real questions",
"minutes": 30,
"objective": "Answer questions whose data is spread across tables: INNER and LEFT JOIN, multi-table joins, GROUP BY with HAVING, and the classic COUNT(*) trap.",
"prerequisites": [
"Demo 4",
"Knowing which columns are foreign keys"
],
"dataset": "university_db (freshly seeded).",
"setup": "university",
"errors": [
[
"ERROR 1055: Expression #2 of SELECT list is not in GROUP BY clause",
"Every selected column must appear in GROUP BY or inside an aggregate such as COUNT, MIN or MAX."
],
[
"ERROR 1052: Column 'StudentID' in field list is ambiguous",
"Two joined tables have that column. Prefix it with the table alias: s.StudentID."
],
[
"A JOIN returns far too many rows",
"A missing or wrong ON condition produces a cross product. Check each ON matches a foreign key."
]
],
"variations": [
"Rewrite the LEFT JOIN query with NOT EXISTS and compare readability.",
"List each course with its coordinator's name (Course JOIN Lecturer on CoordinatorID)."
],
"practice": {
"task": "For each lecturer, show their full name and how many students are registered on the modules they deliver. Include lecturers who deliver no module, with 0.",
"hint": "Start from Lecturer and use LEFT JOIN twice. Count a column from Registration, not *."
},
"steps": [
{
"title": "Two tables: which modules is Ahmed on?",
"say": "The ON condition is exactly a foreign key from Demo 3: the arrows on the ER diagram.",
"sql": "SELECT s.StudentID, s.Forename, s.Surname, r.ModuleCode\nFROM Student AS s\nINNER JOIN Registration AS r ON r.StudentID = s.StudentID\nWHERE s.StudentID = 1001;",
"out": [
{
"sql": "SELECT s.StudentID, s.Forename, s.Surname, r.ModuleCode\nFROM Student AS s\nINNER JOIN Registration AS r ON r.StudentID = s.StudentID\nWHERE s.StudentID = 1001",
"kind": "rows",
"text": "+-----------+----------+---------+------------+\n| StudentID | Forename | Surname | ModuleCode |\n+-----------+----------+---------+------------+\n|      1001 | Ahmed    | Ali     | COM745     |\n|      1001 | Ahmed    | Ali     | COM746     |\n+-----------+----------+---------+------------+\n2 rows in set"
}
]
},
{
"title": "Three tables: names, not codes",
"say": "Normalisation split the data apart; JOIN puts it back together whenever we need it.",
"sql": "SELECT s.Forename, s.Surname, m.ModuleName\nFROM Student AS s\nJOIN Registration AS r ON r.StudentID  = s.StudentID\nJOIN Module       AS m ON m.ModuleCode = r.ModuleCode\nWHERE s.CourseCode = 'MSCDS'\nORDER BY s.Surname, m.ModuleName;",
"out": [
{
"sql": "SELECT s.Forename, s.Surname, m.ModuleName\nFROM Student AS s\nJOIN Registration AS r ON r.StudentID  = s.StudentID\nJOIN Module       AS m ON m.ModuleCode = r.ModuleCode\nWHERE s.CourseCode = 'MSCDS'\nORDER BY s.Surname, m.ModuleName",
"kind": "rows",
"text": "+----------+----------+-----------------------------------+\n| Forename | Surname  | ModuleName                        |\n+----------+----------+-----------------------------------+\n| Emma     | Brown    | Data Science and Machine Learning |\n| Omar     | Farouk   | Big Data and Infrastructure       |\n| Kwame    | Mensah   | Data Science and Machine Learning |\n| Sofia    | Rossi    | Big Data and Infrastructure       |\n| Arjun    | Singh    | Data Science and Machine Learning |\n| Grace    | Thompson | Big Data and Infrastructure       |\n| Wei      | Zhang    | Big Data and Infrastructure       |\n| Wei      | Zhang    | Data Science and Machine Learning |\n+----------+----------+-----------------------------------+\n8 rows in set"
}
]
},
{
"title": "Four tables: who teaches Sarah's modules?",
"sql": "SELECT s.Forename AS Student, m.ModuleCode, m.ModuleName,\n       CONCAT(l.Forename, ' ', l.Surname) AS Lecturer\nFROM Student AS s\nJOIN Registration AS r ON r.StudentID  = s.StudentID\nJOIN Module       AS m ON m.ModuleCode = r.ModuleCode\nJOIN Lecturer     AS l ON l.LecturerID = m.LecturerID\nWHERE s.StudentID = 1002;",
"out": [
{
"sql": "SELECT s.Forename AS Student, m.ModuleCode, m.ModuleName,\n       CONCAT(l.Forename, ' ', l.Surname) AS Lecturer\nFROM Student AS s\nJOIN Registration AS r ON r.StudentID  = s.StudentID\nJOIN Module       AS m ON m.ModuleCode = r.ModuleCode\nJOIN Lecturer     AS l ON l.LecturerID = m.LecturerID\nWHERE s.StudentID = 1002",
"kind": "rows",
"text": "+---------+------------+-----------------------------------+-------------+\n| Student | ModuleCode | ModuleName                        | Lecturer    |\n+---------+------------+-----------------------------------+-------------+\n| Sarah   | COM745     | Big Data and Infrastructure       | Emily Brown |\n| Sarah   | COM747     | Data Science and Machine Learning | Mei Chen    |\n+---------+------------+-----------------------------------+-------------+\n2 rows in set"
}
]
},
{
"title": "LEFT JOIN: who is missing?",
"ask": "John Smith (1003) has no registrations. Does he appear in an INNER JOIN?",
"say": "INNER JOIN keeps only matching rows. LEFT JOIN keeps every row from the left table and fills the gaps with NULL; WHERE ... IS NULL then finds the unmatched ones.",
"sql": "SELECT s.StudentID, s.Forename, s.Surname, r.ModuleCode\nFROM Student AS s\nLEFT JOIN Registration AS r ON r.StudentID = s.StudentID\nWHERE r.ModuleCode IS NULL;",
"out": [
{
"sql": "SELECT s.StudentID, s.Forename, s.Surname, r.ModuleCode\nFROM Student AS s\nLEFT JOIN Registration AS r ON r.StudentID = s.StudentID\nWHERE r.ModuleCode IS NULL",
"kind": "rows",
"text": "+-----------+----------+---------+------------+\n| StudentID | Forename | Surname | ModuleCode |\n+-----------+----------+---------+------------+\n|      1003 | John     | Smith   | NULL       |\n+-----------+----------+---------+------------+\n1 row in set"
}
]
},
{
"title": "COUNT(*) versus COUNT(column)",
"ask": "COM750 has no students. What should its count be?",
"say": "With a LEFT JOIN, COUNT(*) counts the NULL-filled row as 1. COUNT(r.StudentID) ignores NULLs and gives the honest 0.",
"sql": "SELECT m.ModuleCode,\n       COUNT(*)           AS CountStar,\n       COUNT(r.StudentID) AS CountStudents\nFROM Module AS m\nLEFT JOIN Registration AS r ON r.ModuleCode = m.ModuleCode\nGROUP BY m.ModuleCode\nORDER BY m.ModuleCode;",
"out": [
{
"sql": "SELECT m.ModuleCode,\n       COUNT(*)           AS CountStar,\n       COUNT(r.StudentID) AS CountStudents\nFROM Module AS m\nLEFT JOIN Registration AS r ON r.ModuleCode = m.ModuleCode\nGROUP BY m.ModuleCode\nORDER BY m.ModuleCode",
"kind": "rows",
"text": "+------------+-----------+---------------+\n| ModuleCode | CountStar | CountStudents |\n+------------+-----------+---------------+\n| COM745     |         7 |             7 |\n| COM746     |         5 |             5 |\n| COM747     |         6 |             6 |\n| COM748     |         4 |             4 |\n| COM750     |         1 |             0 |\n| COM760     |         4 |             4 |\n+------------+-----------+---------------+\n6 rows in set"
}
]
},
{
"title": "GROUP BY with HAVING",
"say": "WHERE filters rows before grouping; HAVING filters groups after aggregation.",
"sql": "SELECT c.CourseName, COUNT(*) AS Students\nFROM Course AS c\nJOIN Student AS s ON s.CourseCode = c.CourseCode\nGROUP BY c.CourseName\nHAVING COUNT(*) > 5\nORDER BY Students DESC;",
"out": [
{
"sql": "SELECT c.CourseName, COUNT(*) AS Students\nFROM Course AS c\nJOIN Student AS s ON s.CourseCode = c.CourseCode\nGROUP BY c.CourseName\nHAVING COUNT(*) > 5\nORDER BY Students DESC",
"kind": "rows",
"text": "+-------------------------------------+----------+\n| CourseName                          | Students |\n+-------------------------------------+----------+\n| MSc Computer Science and Technology |       12 |\n| MSc Data Science                    |        7 |\n+-------------------------------------+----------+\n2 rows in set"
}
]
},
{
"title": "A common error: ONLY_FULL_GROUP_BY",
"ask": "Why does MySQL refuse this?",
"say": "Each group (a module) has many students, so \"the\" StudentID is undefined. Every selected column must be grouped or aggregated. MySQL 8 enforces this by default; MySQL 5.6 and earlier did not, so old answers online may work there and fail here.",
"sql": "SELECT ModuleCode, StudentID, COUNT(*)\nFROM Registration\nGROUP BY ModuleCode;",
"out": [
{
"sql": "SELECT ModuleCode, StudentID, COUNT(*)\nFROM Registration\nGROUP BY ModuleCode",
"kind": "error",
"text": "ERROR 1055 (42000): Expression #2 of SELECT list is not in GROUP BY clause and contains nonaggregated column 'university_db.Registration.StudentID' which is not functionally dependent on columns in GROUP BY clause; this is incompatible with sql_mode=only_full_group_by"
}
]
}
]
},
{
"id": "mysql-06-index-acid",
"num": 6,
"title": "Indexes, transactions and views",
"minutes": 25,
"objective": "See an index change the query plan, use a transaction to keep an enrolment all-or-nothing, and hide a JOIN behind a view.",
"prerequisites": [
"Demos 4 and 5"
],
"dataset": "university_db (freshly seeded).",
"setup": "university",
"errors": [
[
"ERROR 1061: Duplicate key name",
"The index already exists. DROP INDEX idx_student_surname ON Student; then create it again."
],
[
"Changes vanish after closing Workbench",
"A transaction was left open without COMMIT. Workbench has an auto-commit toggle on the SQL editor toolbar."
]
],
"variations": [
"Bank transfer version: two UPDATEs on an Account table inside one transaction, then ROLLBACK.",
"Create a composite index on Registration (ModuleCode, RegistrationDate) and EXPLAIN a query that filters on both."
],
"practice": {
"task": "Create a view ModuleRoster showing ModuleCode, ModuleName, lecturer surname and the number of registered students for every module, including modules with none. Query it for modules with fewer than 5 students.",
"hint": "LEFT JOIN Registration and COUNT a Registration column. Filter the view with WHERE, not HAVING."
},
"steps": [
{
"title": "Without an index: a full scan",
"say": "Back to the phone book: finding a surname with no alphabetical order means reading every entry. type = ALL means a full table scan; rows is the optimiser's estimate.",
"sql": "EXPLAIN SELECT * FROM Student WHERE Surname = 'Khan';",
"trimmed": true,
"out": [
{
"sql": "EXPLAIN SELECT * FROM Student WHERE Surname = 'Khan'",
"kind": "rows",
"text": "+----+-------------+---------+------+---------------+------+------+-------------+\n| id | select_type | table   | type | possible_keys | key  | rows | Extra       |\n+----+-------------+---------+------+---------------+------+------+-------------+\n|  1 | SIMPLE      | Student | ALL  | NULL          | NULL |   24 | Using where |\n+----+-------------+---------+------+---------------+------+------+-------------+\n1 row in set"
}
]
},
{
"title": "Add an index and look again",
"say": "type = ref and key = idx_student_surname: MySQL now jumps straight to the matching entries. With only 24 rows the time saved is invisible; with millions it is the difference between milliseconds and minutes.",
"sql": "CREATE INDEX idx_student_surname ON Student (Surname);\nEXPLAIN SELECT * FROM Student WHERE Surname = 'Khan';",
"trimmed": true,
"out": [
{
"sql": "CREATE INDEX idx_student_surname ON Student (Surname)",
"kind": "ok",
"text": "Query OK, 0 rows affected"
},
{
"sql": "EXPLAIN SELECT * FROM Student WHERE Surname = 'Khan'",
"kind": "rows",
"text": "+----+-------------+---------+------+---------------------+---------------------+------+-------+\n| id | select_type | table   | type | possible_keys       | key                 | rows | Extra |\n+----+-------------+---------+------+---------------------+---------------------+------+-------+\n|  1 | SIMPLE      | Student | ref  | idx_student_surname | idx_student_surname |    1 | NULL  |\n+----+-------------+---------+------+---------------------+---------------------+------+-------+\n1 row in set"
}
]
},
{
"title": "Indexes MySQL made for you",
"say": "Every PRIMARY KEY and UNIQUE constraint gets an index automatically, and InnoDB indexes each foreign key. Indexes speed up reads but cost storage and slow every write, so index what people search and join on.",
"sql": "SHOW INDEX FROM Student;",
"trimmed": true,
"out": [
{
"sql": "SHOW INDEX FROM Student",
"kind": "rows",
"text": "+---------+------------+---------------------+--------------+-------------+\n| Table   | Non_unique | Key_name            | Seq_in_index | Column_name |\n+---------+------------+---------------------+--------------+-------------+\n| Student |          0 | PRIMARY             |            1 | StudentID   |\n| Student |          0 | uq_student_email    |            1 | Email       |\n| Student |          1 | fk_student_course   |            1 | CourseCode  |\n| Student |          1 | idx_student_surname |            1 | Surname     |\n+---------+------------+---------------------+--------------+-------------+\n4 rows in set"
}
]
},
{
"title": "A transaction that goes wrong",
"ask": "Enrolling a student means a Student row and Registration rows. If the second insert fails, should the first stand?",
"say": "The failed statement is undone, but the earlier insert is still there inside the transaction. MySQL does not roll back the whole transaction for you; the application (or you) decides to ROLLBACK. That is atomicity in practice.",
"sql": "START TRANSACTION;\nINSERT INTO Student (StudentID, Forename, Surname, Email, EnrolmentLevel, CourseCode)\nVALUES (1026, 'Leah', 'Ward', 'leah.ward@students.example.ac.uk', 7, 'MSCDS');\nINSERT INTO Registration (StudentID, ModuleCode, RegistrationDate, Semester)\nVALUES (1026, 'COM999', '2026-09-30', 'Semester 1');\nSELECT StudentID, Forename FROM Student WHERE StudentID = 1026;\nROLLBACK;\nSELECT StudentID, Forename FROM Student WHERE StudentID = 1026;",
"out": [
{
"sql": "START TRANSACTION",
"kind": "ok",
"text": "Query OK, 0 rows affected"
},
{
"sql": "INSERT INTO Student (StudentID, Forename, Surname, Email, EnrolmentLevel, CourseCode)\nVALUES (1026, 'Leah', 'Ward', 'leah.ward@students.example.ac.uk', 7, 'MSCDS')",
"kind": "ok",
"text": "Query OK, 1 row affected"
},
{
"sql": "INSERT INTO Registration (StudentID, ModuleCode, RegistrationDate, Semester)\nVALUES (1026, 'COM999', '2026-09-30', 'Semester 1')",
"kind": "error",
"text": "ERROR 1452 (23000): Cannot add or update a child row: a foreign key constraint fails (`university_db`.`Registration`, CONSTRAINT `fk_registration_module` FOREIGN KEY (`ModuleCode`) REFERENCES `Module` (`ModuleCode`))"
},
{
"sql": "SELECT StudentID, Forename FROM Student WHERE StudentID = 1026",
"kind": "rows",
"text": "+-----------+----------+\n| StudentID | Forename |\n+-----------+----------+\n|      1026 | Leah     |\n+-----------+----------+\n1 row in set"
},
{
"sql": "ROLLBACK",
"kind": "ok",
"text": "Query OK, 0 rows affected"
},
{
"sql": "SELECT StudentID, Forename FROM Student WHERE StudentID = 1026",
"kind": "rows",
"text": "Empty set"
}
]
},
{
"title": "The same enrolment, committed",
"sql": "START TRANSACTION;\nINSERT INTO Student (StudentID, Forename, Surname, Email, EnrolmentLevel, CourseCode)\nVALUES (1026, 'Leah', 'Ward', 'leah.ward@students.example.ac.uk', 7, 'MSCDS');\nINSERT INTO Registration (StudentID, ModuleCode, RegistrationDate, Semester)\nVALUES (1026, 'COM747', '2026-09-30', 'Semester 1');\nCOMMIT;\nSELECT s.StudentID, s.Forename, r.ModuleCode\nFROM Student s JOIN Registration r ON r.StudentID = s.StudentID\nWHERE s.StudentID = 1026;",
"out": [
{
"sql": "START TRANSACTION",
"kind": "ok",
"text": "Query OK, 0 rows affected"
},
{
"sql": "INSERT INTO Student (StudentID, Forename, Surname, Email, EnrolmentLevel, CourseCode)\nVALUES (1026, 'Leah', 'Ward', 'leah.ward@students.example.ac.uk', 7, 'MSCDS')",
"kind": "ok",
"text": "Query OK, 1 row affected"
},
{
"sql": "INSERT INTO Registration (StudentID, ModuleCode, RegistrationDate, Semester)\nVALUES (1026, 'COM747', '2026-09-30', 'Semester 1')",
"kind": "ok",
"text": "Query OK, 1 row affected"
},
{
"sql": "COMMIT",
"kind": "ok",
"text": "Query OK, 0 rows affected"
},
{
"sql": "SELECT s.StudentID, s.Forename, r.ModuleCode\nFROM Student s JOIN Registration r ON r.StudentID = s.StudentID\nWHERE s.StudentID = 1026",
"kind": "rows",
"text": "+-----------+----------+------------+\n| StudentID | Forename | ModuleCode |\n+-----------+----------+------------+\n|      1026 | Leah     | COM747     |\n+-----------+----------+------------+\n1 row in set"
}
]
},
{
"title": "A view hides the JOIN",
"say": "A view is a saved query that behaves like a table. It is also a security tool: give someone access to the view without names or emails.",
"sql": "CREATE VIEW StudentModules AS\nSELECT s.StudentID, s.Forename, s.Surname, m.ModuleCode, m.ModuleName\nFROM Student s\nJOIN Registration r ON r.StudentID  = s.StudentID\nJOIN Module       m ON m.ModuleCode = r.ModuleCode;\nSELECT * FROM StudentModules WHERE Surname = 'Ali';",
"out": [
{
"sql": "CREATE VIEW StudentModules AS\nSELECT s.StudentID, s.Forename, s.Surname, m.ModuleCode, m.ModuleName\nFROM Student s\nJOIN Registration r ON r.StudentID  = s.StudentID\nJOIN Module       m ON m.ModuleCode = r.ModuleCode",
"kind": "ok",
"text": "Query OK, 0 rows affected"
},
{
"sql": "SELECT * FROM StudentModules WHERE Surname = 'Ali'",
"kind": "rows",
"text": "+-----------+----------+---------+------------+-----------------------------+\n| StudentID | Forename | Surname | ModuleCode | ModuleName                  |\n+-----------+----------+---------+------------+-----------------------------+\n|      1001 | Ahmed    | Ali     | COM745     | Big Data and Infrastructure |\n|      1001 | Ahmed    | Ali     | COM746     | Database Systems            |\n+-----------+----------+---------+------------+-----------------------------+\n2 rows in set"
}
]
}
]
}
